local function animateMove(move_str, move_cells, target_chess_cells)

    -- FIX: Verify En Passant by ensuring the target cell is EMPTY *before* the move
    local isEnPassant = false
    local targetMob = RPD.Actor:findChar(move_cells[2])
    if enPassantMoves[move_str] and not targetMob then
        local movedMob = RPD.Actor:findChar(move_cells[1])
        if movedMob and movedMob:getEntityKind() == 'Rat' then
            isEnPassant = true
        end
    end

    movePiece(move_cells[1], move_cells[2])

    -- caveman: promotion. pawn (Rat) reach last rank -> swap to Warlock (queen).
    local destRank = tonumber(string.sub(target_chess_cells[2], 2, 2))
    local destMob = RPD.Actor:findChar(move_cells[2])
    if destMob and destMob:getEntityKind() == 'Rat' and (destRank == 1 or destRank == 8) then
        destMob:die(destMob)
        local queen = RPD.MobFactory:mobByName('Warlock')
        queen:setPos(move_cells[2])
        RPD.setAi(queen, 'PASSIVE')
        RPD.Dungeon.level:spawnMob(queen)
        queen:getSprite():tint(destRank == 8 and 0xFF0000 or 0x0000FF, 0.5)
    end

    -- FIX: Castling - Ensure the piece that just moved is actually a King
    if castleMoves[move_str] and destMob and destMob:getEntityKind() == 'King' then
        local rookMove = rookMoves[move_str]
        local cells = { cellFromChessCell(string.sub(rookMove, 1, 2)),
                        cellFromChessCell(string.sub(rookMove, 3, 4)) }
        movePiece(cells[1], cells[2])
    end

    -- caveman: en passant. captured pawn beside destination, remove it.
    if isEnPassant then
        local pawnCell = pawnVictim[move_str]
        local cell = cellFromChessCell(pawnCell)
        local mob = RPD.Actor:findChar(cell)
        if mob then
            mob:die(mob)
        end
    end
end

local function highlightCells(cells)
    RPD.Sfx.HighlightCell:removeAll()

    for k, cell in pairs(cells) do
        local pos = cellFromChessCell(cell)
        RPD.Sfx.HighlightCell:add(pos)
    end
end

local gameInProgress = true

local function processLose()
    RPD.glog("You Lose!")
    restorePets()
    RPD.Dungeon.hero:die(RPD.Dungeon.hero)
    gameInProgress = false
end

local function processWin()
    restorePets()
    local mobs = RPD.Dungeon.level.mobs
    local iterator = mobs:iterator()
    local mobsToDie = {}

    while iterator:hasNext() do
        local mob = iterator:next()
        -- FIX: Prevent mass-extinction of pets/merchants. Only target chess pieces.
        local kind = mob:getEntityKind()
        local isChessPiece = false
        for _, pieceName in pairs(pieces_set) do
            if pieceName == kind then
                isChessPiece = true
                break
            end
        end

        if isChessPiece then
            table.insert(mobsToDie, mob)
        end
    end

    for i,mob in ipairs(mobsToDie) do
        mob:die(RPD.Dungeon.hero)
    end

    RPD.glog("You Win!")

    local level = RPD.Dungeon.level
    local origin = level:getProperty("chessBoardOrigin", "")

    -- caveman: prize chest at board centre (both paths).
    local centerCell = cellFromChessCell("e4")
    local prize = RPD.ItemFactory:itemByName("WandOfFirebolt")
    local heap = level:drop(prize, centerCell)
    heap.type = RPD.Heap.Type.CHEST
    heap.sprite:drop(centerCell)

    if origin and origin ~= "" then
        -- caveman: CityBossLevel. King defeated via chess. Java clears board + badge + unlocks exit.
        level:onChessWin()
    else
        -- caveman: chess_level debug. fill chasm ring + exit portal to town.
        for x = 3, 12 do
            for y = 3, 12 do
                level:set(level:cell(x, y), RPD.Terrain.EMPTY)
            end
        end
        RPD.GameScene:updateMap()

        RPD.createLevelObject(
                {kind = "PortalGateSender", target = {levelId = "town_2", x = 12, y = 28}},
                cellFromChessCell("e2")
        )
    end

    gameInProgress = false
end

local AI_DELAY_MS = 800
local aiMoveAt = 0
local allowedMoves = {}

local function getPiece(board, engineCell)
    return string.sub(board, engineCell+1, engineCell + 1)
end

return actor.init({
    act = function()
        return true
    end,

    onStep = function()
        if #scheduledMoves > 0 then
            if RPD.SystemTime:now() - aiMoveAt >= AI_DELAY_MS then
                local m = scheduledMoves[1]
                animateMove(m[1], m[2], m[3])

                -- FIX: Process delayed win/loss so the final move is visible
                local match_end = m[4]
                table.remove(scheduledMoves, 1)

                if match_end == "win" then
                    processWin()
                elseif match_end == "lose" then
                    processLose()
                end
            end
        end
    end,

    actionTime = function()
