            -- caveman: freeze hero pets so they not walk board / kill pieces / get captured.
            -- save their ai tag now, restore when game ends (processWin / processLose).
            frozenPets = {}
            local mobsIter = RPD.Dungeon.level.mobs:iterator()
            while mobsIter:hasNext() do
                local mob = mobsIter:next()
                if mob:isPet() then
                    frozenPets[#frozenPets + 1] = { mob = mob, tag = mob:getState():getTag() }
                    RPD.setAi(mob, "PASSIVE")
                end
            end

            local level = RPD.Dungeon.level

            local boardData = util.split(chess.board, "\n")
            for i, v in ipairs(boardData) do
                print(v)
                if i >= 3 and i <= 10 then
                    local y = i - 2
                    local cell = cellFromChess(0, y)

                    for ii = 1, 8 do
                        local chessCell = chessCellFromCell(cell)
                        local piece = string.sub(v, ii + 1, ii + 1)

                        if pieces_set[piece] then
                            local mob = RPD.MobFactory:mobByName(pieces_set[piece])

                            mob:setPos(cell)
