                            level:spawnMob(mob)

                            if piece == piece:upper() then
                                mob:getSprite():tint(0xFF0000, 0.5)
                            else
                                mob:getSprite():tint(0x0000FF, 0.5)
                            end

                            pieces[chessCell] = mob
                        end
